        ['renewal_upcoming', 'Upcoming renewal', 'Your {{company}} subscription renews in {{days}} day(s)',
         '<p>Hello {{name}},</p><p>The subscription for <strong>{{estate_name}}</strong> is due on <strong>{{due_date}}</strong> ({{amount}}). Pay early to avoid any interruption.</p><p><a href="{{link}}">View invoice and pay</a></p>',
         'name, estate_name, days, due_date, amount, link, company'],
        ['payment_due', 'Payment due today', 'Payment due today for {{estate_name}}',
