         'name, estate_name, grace_ends, link, company'],
        ['grace_reminder', 'Grace period reminder', 'Reminder: {{days_left}} day(s) left before suspension',
         '<p>Hello {{name}},</p><p>This is a reminder that <strong>{{estate_name}}</strong> will be suspended on <strong>{{grace_ends}}</strong> unless payment is received. <a href="{{link}}">Pay now</a>.</p>',
         'name, estate_name, days_left, grace_ends, link, company'],
        ['suspension_warning', 'Suspension warning', 'Final warning: {{estate_name}} will be suspended on {{grace_ends}}',
