         'name, estate_name, retention_ends, retention_days, link, company'],
        ['retention_warning', 'Retention period warning', '{{days_left}} day(s) left to recover {{estate_name}}',
         '<p>Hello {{name}},</p><p>The data for <strong>{{estate_name}}</strong> will be eligible for permanent deletion on <strong>{{retention_ends}}</strong>. Renew now to recover your estate, or <a href="{{export_link}}">export your data</a>.</p><p><a href="{{link}}">Renew now</a></p>',
         'name, estate_name, days_left, retention_ends, link, export_link, company'],
        ['final_deletion_warning', 'Final deletion warning', 'FINAL NOTICE: {{estate_name}} will be permanently deleted',
         '<p>Hello {{name}},</p><p>This is the final notice. Unless the subscription is renewed, <strong>{{estate_name}}</strong> will be permanently deleted after <strong>{{deletion_date}}</strong>. This cannot be undone. <a href="{{link}}">Renew now</a>.</p>',
