        ['plan_changed', 'Plan change confirmation', 'Your plan change for {{estate_name}}',
         '<p>Hello {{name}},</p><p>Your plan change to <strong>{{plan}}</strong> takes effect on <strong>{{effective}}</strong>.</p>',
