    $st = $db->prepare("INSERT IGNORE INTO email_templates (template_key, name, subject, body_html, placeholders) VALUES (?,?,?,?,?)");
    foreach ($t as $r) { $st->bind_param('sssss', $r[0], $r[1], $r[2], $r[3], $r[4]); $st->execute(); }
